mapper.select:

where v.product_key = #{productKey}
  and v.device_id = #{deviceId}
  and v.package_type = #{packageType}
  and COALESCE(v.module, 'APPLICATION') = #{module}
limit 1


where v.product_key = #{productKey}
  and v.device_id = #{deviceId}
order by v.last_report_time desc, v.update_time desc, v.id desc
limit 1
